package dev.astralreach.hytale;
import com.hypixel.hytale.component.*;
import com.hypixel.hytale.server.core.modules.entity.component.TransformComponent;
import com.hypixel.hytale.server.core.entity.entities.Player;
import com.hypixel.hytale.server.core.universe.*;
import com.hypixel.hytale.server.core.universe.world.World;
import com.hypixel.hytale.server.core.universe.world.storage.EntityStore;
import com.hypixel.hytale.math.vector.*;
import dev.astralreach.core.*;
import org.joml.Vector3d;
import java.util.*;
/** Saved individual moorings; transient nose-first approach/release cameras and real passenger movement. */
final class StationDocks {
 private record Ship(Store<EntityStore>store,Ref<EntityStore>ref,UUID station,int port,LaunchPlan plan){}
 private static final class Transit{final StationRegistry.Station station;final StationRegistry.Mooring mooring;final boolean departing,home;final World orbit;long started;Transit(StationRegistry.Station s,StationRegistry.Mooring m,boolean d,boolean h,World orbit){station=s;mooring=m;departing=d;home=h;this.orbit=orbit;}}
 private static final Map<String,Long>closing=new HashMap<>();
 private static final Map<UUID,Ship>ships=new HashMap<>();private static final Map<UUID,Transit>transits=new HashMap<>();
 static boolean inTransit(UUID p){return transits.containsKey(p);}
 private static Vector3d vector(StationDocking.Point p){return new Vector3d(p.x(),p.y(),p.z());}
 static void dock(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,StationRegistry.Station st){if(inTransit(p.getUuid()))throw new IllegalArgumentException("Your docking sequence is already running.");var m=st.reserve(p.getUuid(),StationService.paid(s,r).plan);if(!StationStructure.ready(s.getExternalData().getWorld(),st,m.port())){st.moorings.remove(p.getUuid());throw new IllegalArgumentException("The station's nine-airlock concourse is still assembling. Your return reserve is retained.");}start(s,r,p,new Transit(st,m,false,false,null));}
 static void depart(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,boolean home,World orbit){if(inTransit(p.getUuid()))return;var f=StationService.paid(s,r);var st=StationService.data(s).stations.get(f.stationOwner);var m=st==null?null:st.moorings.get(p.getUuid());if(m==null||!StationStructure.ready(s.getExternalData().getWorld(),st,m.port())){leave(s,r,p,home,orbit);return;}start(s,r,p,new Transit(st,m,true,home,orbit));}
 private static void start(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,Transit t){var f=StationService.paid(s,r);SpaceFlight.handoff(s,r,p);f.stationOwner=t.station.owner;f.stationPort=t.mooring.port();f.boarded=true;transits.put(p.getUuid(),t);SpaceFlight.begin(s,r,p,false);var pose=StationDocking.pose(t.station.layout,t.mooring.port(),t.mooring.plan(),0,t.departing);RocketService.teleport(s,r,p,s.getExternalData().getWorld(),new Transform(pose.crew().x(),pose.crew().y(),pose.crew().z()),()->{t.started=System.nanoTime();if(t.departing)RocketService.cue(s,p,"AR_Airlock_Release",StationService.cell(t.station.layout.port(t.mooring.port())));});}
 static void recover(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,StationRegistry.Station st){var f=StationService.paid(s,r);var m=st.reserve(p.getUuid(),f.plan);f.stationPort=m.port();if(f.boarded&&!inTransit(p.getUuid())&&StationStructure.ready(s.getExternalData().getWorld(),st,m.port()))finishDock(s,r,p,st,m);}
 private static void finishDock(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,StationRegistry.Station st,StationRegistry.Mooring m){transits.remove(p.getUuid());var f=StationService.paid(s,r);SpaceFlight.handoff(s,r,p);f.stationOwner=st.owner;f.stationPort=m.port();f.boarded=false;var a=st.layout.portArrival(m.port());RocketService.teleport(s,r,p,s.getExternalData().getWorld(),new Transform(a.x()+.5,a.y()+.02,a.z()+.5),()->{RocketService.cue(s,p,"AR_Station_Dock",StationService.cell(st.layout.port(m.port())));AstralReachPlugin.message(p,"Docked at airlock "+String.format(java.util.Locale.ROOT,"%02d",m.port()+1)+". Follow the protected concourse to the starter platforms. Return fuel remains protected.");});}
 private static void leave(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,boolean home,World orbit){var f=StationService.paid(s,r);var st=StationService.data(s).stations.get(f.stationOwner);if(st!=null)st.moorings.remove(p.getUuid());transits.remove(p.getUuid());remove(p.getUuid(),s);SpaceFlight.handoff(s,r,p);f.stationOwner=null;f.stationPort=-1;f.boarded=true;RocketService.teleport(s,r,p,orbit,new Transform(SpaceFlight.slot(p)+.5,202+FlightTimeline.crewHeight(f.plan),.5),()->{if(home){var ref=p.getReference();if(ref!=null&&ref.isValid())RocketService.returnHome(ref.getStore(),ref,p);}});}
 static void tick(Store<EntityStore>s){var w=s.getExternalData().getWorld();var active=new HashSet<UUID>();
  for(var p:w.getPlayerRefs()){var r=p.getReference();if(r==null||!r.isValid()||r.getStore()!=s)continue;var t=transits.get(p.getUuid());if(t==null)continue;var f=s.getComponent(r,AstralReachPlugin.flightType);if(f==null||f.trip==null||!t.station.owner.equals(f.stationOwner)){transits.remove(p.getUuid());continue;}double elapsed=t.started==0?0:(System.nanoTime()-t.started)/1e9;var pose=StationDocking.pose(t.station.layout,t.mooring.port(),t.mooring.plan(),elapsed,t.departing);sync(s,t.station,t.mooring,pose);SpaceFlight.cinematic(s,r,p,vector(pose.crew()),vector(pose.camera()),vector(pose.target()),(t.departing?"Releasing airlock ":elapsed<10?"Approaching airlock ":"Docking clamps secured · airlock ")+String.format(java.util.Locale.ROOT,"%02d",t.mooring.port()+1));if(elapsed>=StationDocking.SECONDS){if(t.departing)leave(s,r,p,t.home,t.orbit);else finishDock(s,r,p,t.station,t.mooring);}}
  for(var st:StationService.data(s).stations.values()){if(st.shellVersion!=2)continue;for(var m:st.moorings.values()){active.add(m.player());if(!transits.containsKey(m.player()))sync(s,st,m,StationDocking.pose(st.layout,m.port(),m.plan(),12,false));}for(int port=0;port<StationLayout.PORTS;port++){boolean open=false;for(var m:st.moorings.values())if(m.port()==port){var t=transits.get(m.player());open=t==null||!t.departing&&t.started!=0&&(System.nanoTime()-t.started)>10_000_000_000L;break;}String key=st.owner+":"+port;var at=StationService.cell(st.layout.port(port));var block=NativeBlocks.get(w,at);if(open)closing.remove(key);else if(block!=null&&block.getId().endsWith("Open"))closing.putIfAbsent(key,System.nanoTime());Long since=closing.get(key);String phase=open?"Open":since!=null&&System.nanoTime()-since<600_000_000L?"Closing":"";if(since!=null&&phase.isEmpty())closing.remove(key);NativeBlocks.stateOf(w,at,"AR_StationAirlock",String.format(java.util.Locale.ROOT,"D%02d",port+1)+phase);}}
  for(var e:new ArrayList<>(ships.entrySet()))if(e.getValue().store()==s&&!active.contains(e.getKey()))remove(e.getKey(),s);
  for(var e:new ArrayList<>(transits.entrySet())){var p=Universe.get().getPlayer(e.getKey());if(p==null||p.getReference()==null||p.getReference().getStore()!=s)transits.remove(e.getKey());}
 }
 private static void sync(Store<EntityStore>s,StationRegistry.Station st,StationRegistry.Mooring m,StationDocking.Pose pose){var old=ships.get(m.player());if(old!=null&&(old.store()!=s||!old.station().equals(st.owner)||old.port()!=m.port()||old.plan()!=m.plan())){remove(m.player(),s);old=null;}if(old==null||!old.ref().isValid()){var ref=RocketVisuals.spawn(s,m.plan().asset("ShipIdle"),vector(pose.base()),new Rotation3f((float)pose.pitch(),0,0));if(ref==null)return;old=new Ship(s,ref,st.owner,m.port(),m.plan());ships.put(m.player(),old);}var transform=s.getComponent(old.ref(),TransformComponent.getComponentType());transform.setPosition(vector(pose.base()));transform.setRotation(new Rotation3f((float)pose.pitch(),0,0));}
 private static void remove(UUID p,Store<EntityStore>s){var old=ships.remove(p);if(old!=null&&old.store()==s&&old.ref().isValid())s.removeEntity(old.ref(),RemoveReason.REMOVE);}
 private StationDocks(){}
}
